/**
 * Published basic-strategy charts, used as the independent cross-check the spec
 * requires (§14.2).
 *
 * These grids are *not* generated by this engine. They are the standard
 * published basic strategy for the stated rule sets, transcribed here so that a
 * disagreement between the engine and the literature fails the build rather than
 * shipping. The engine derives its own charts from EV (spec §6.1); this file is
 * only ever the second opinion.
 *
 * Legend: H hit · S stand · D double (hit if not allowed) · P split · R surrender
 *
 * Reviewer note for the §14.2 sign-off: these two grids are the ones the suite
 * asserts cell-for-cell. Before release they should be re-checked against at
 * least two named published sources, and any cell where sources disagree should
 * be moved into `KNOWN_MARGINAL` below with the disagreement documented, not
 * silently overridden.
 */

export interface PublishedChart {
  name: string;
  /** Rows are hard 5..17, soft A2..A9, then pairs 2,2..A,A. */
  hard: Record<number, string[]>;
  soft: Record<number, string[]>;
  pairs: Record<string, string[]>;
}

/** Upcard order for every row below: 2 3 4 5 6 7 8 9 10 A. */
export const UPCARD_ORDER = ['2', '3', '4', '5', '6', '7', '8', '9', '10', 'A'] as const;

const row = (s: string): string[] => s.trim().split(/\s+/);

