/**
 * Cells where published sources legitimately disagree, usually because the two
 * actions are within a rounding error of each other. The spec is explicit that
 * these are documented as known-marginal rather than silently overridden
 * (§14.2), so the chart test reports them instead of failing on them.
 *
 * Keyed by scenario key. Empty until a real disagreement is found during the
 * §14.2 review; the mechanism is here so that resolving one is a data change.
 */
export const KNOWN_MARGINAL: ReadonlyMap<string, string> = new Map<string, string>();

/**
 * Rule-set deviations that are individually famous, asserted on their own rather
 * than as whole grids. Each is a discrete, well-attested consequence of one rule
 * changing, which makes it a sharp test of whether the engine really computes
 * from the rules rather than reciting a chart.
 */
